-- =====================================================================
-- Mise à jour n°19 du 24/11/2026 : sous-profils Bureautique et nouvelles formations Excel / Word / PowerPoint
--   À lancer APRÈS la mise à jour n°18 (qui crée les formations).
--   1. Les 5 sous-profils Bureautique existants : les nouvelles formations passent en tête (Pourquoi, argumentaire).
--      Les anciens « Le plus adapté : … » deviennent « Ensuite, pour aller plus loin : … ».
--   2. Trois nouveaux sous-profils : Débutant(e) / reprise d'activité / reconversion (bur-006),
--      Secrétaire, assistant(e), agent d'accueil (bur-007), Utilisateur(trice) d'Excel autodidacte (bur-008).
--   3. Domaine Bureautique : familles « Emploi et transition » et « Accueil et relation client ».
--   4. Excel initiation à expert : questionnaire de positionnement Excel obligatoire.
-- À coller dans Supabase › SQL Editor › New query, puis « Run ». Le relancer ne change rien.
-- =====================================================================

update public.profils set data = jsonb_set(data, '{parcours}', $j$[{"formation": "bur-excel-perfectionnement", "pourquoi": "À vérifier : utilise déjà les formules courantes. Le bon niveau pour des tableaux de bord fiables.", "argumentaire": "Il passe un cap : fonctions de recherche (RECHERCHEX), mise en forme conditionnelle, tableaux croisés dynamiques et graphiques adaptés. Résultat : des analyses et des synthèses produites en quelques minutes à partir de ses données. Certification Tosa, éligible au CPF dès la première formation, sans nombre de jours minimum.", "reponses": {"Formation": "Fonctions de recherche, tableaux croisés dynamiques et graphiques pour analyser ses données."}}, {"formation": "bur-excel-expert", "pourquoi": "S'il maîtrise déjà les tableaux croisés : viser le niveau expert avant Power Tools.", "argumentaire": "Pour l'utilisateur déjà à l'aise avec les tableaux croisés : fonctions avancées, outils d'analyse et de simulation, tableaux de bord élaborés. Résultat : une maîtrise complète d'Excel, reconnue par un score Tosa de niveau expert. Certification Tosa, éligible au CPF dès la première formation, sans nombre de jours minimum.", "reponses": {"Formation": "Fonctions avancées, outils d'analyse et tableaux de bord élaborés."}}]$j$::jsonb || (
    select coalesce(jsonb_agg(case when x->>'pourquoi' like 'Le plus adapté : %' then jsonb_set(x, '{pourquoi}', to_jsonb('Ensuite, pour aller plus loin : ' || substr(x->>'pourquoi', 18))) else x end order by o), '[]'::jsonb)
    from jsonb_array_elements(coalesce(data->'parcours', '[]'::jsonb)) with ordinality t(x, o))), updated_at = now()
where id = 'bur-001' and not exists (select 1 from jsonb_array_elements(coalesce(data->'parcours', '[]'::jsonb)) x where x->>'formation' = 'bur-excel-perfectionnement');

update public.profils set data = jsonb_set(data, '{parcours}', $j$[{"formation": "bur-excel-consolidation", "pourquoi": "À vérifier : sait créer un tableau simple. Pour fiabiliser ses tableaux du quotidien.", "argumentaire": "Il consolide les bases et gagne en autonomie : formules conditionnelles (SI, SOMME.SI), références absolues, tris, filtres et graphiques simples. Résultat : des tableaux du quotidien fiables, plus rapides à mettre à jour. Certification Tosa, éligible au CPF dès la première formation, sans nombre de jours minimum.", "reponses": {"Formation": "Formules conditionnelles, tris, filtres et graphiques pour fiabiliser ses tableaux."}}, {"formation": "bur-word-perfectionnement", "pourquoi": "Pour ses courriers types et documents longs : styles et publipostage.", "argumentaire": "Il gagne du temps sur les documents longs et répétitifs : styles, sommaire automatique, modèles, publipostage pour les courriers en nombre. Résultat : des documents homogènes et des envois groupés sans ressaisie. Certification Tosa, éligible au CPF dès la première formation, sans nombre de jours minimum.", "reponses": {"Formation": "Styles, documents longs, modèles et publipostage."}}]$j$::jsonb || (
    select coalesce(jsonb_agg(case when x->>'pourquoi' like 'Le plus adapté : %' then jsonb_set(x, '{pourquoi}', to_jsonb('Ensuite, pour aller plus loin : ' || substr(x->>'pourquoi', 18))) else x end order by o), '[]'::jsonb)
    from jsonb_array_elements(coalesce(data->'parcours', '[]'::jsonb)) with ordinality t(x, o))), updated_at = now()
where id = 'bur-002' and not exists (select 1 from jsonb_array_elements(coalesce(data->'parcours', '[]'::jsonb)) x where x->>'formation' = 'bur-excel-consolidation');

update public.profils set data = jsonb_set(data, '{parcours}', $j$[{"formation": "bur-excel-perfectionnement", "pourquoi": "À vérifier : utilise déjà les formules courantes. Pour analyser ses indicateurs avec les tableaux croisés.", "argumentaire": "Il passe un cap : fonctions de recherche (RECHERCHEX), mise en forme conditionnelle, tableaux croisés dynamiques et graphiques adaptés. Résultat : des analyses et des synthèses produites en quelques minutes à partir de ses données. Certification Tosa, éligible au CPF dès la première formation, sans nombre de jours minimum.", "reponses": {"Formation": "Fonctions de recherche, tableaux croisés dynamiques et graphiques pour analyser ses données."}}]$j$::jsonb || (
    select coalesce(jsonb_agg(case when x->>'pourquoi' like 'Le plus adapté : %' then jsonb_set(x, '{pourquoi}', to_jsonb('Ensuite, pour aller plus loin : ' || substr(x->>'pourquoi', 18))) else x end order by o), '[]'::jsonb)
    from jsonb_array_elements(coalesce(data->'parcours', '[]'::jsonb)) with ordinality t(x, o))), updated_at = now()
