update public.profils set data = jsonb_set(data, '{parcours}', $j$[{"formation": "bur-excel-consolidation", "pourquoi": "Pour construire lui-même des tableaux de suivi fiables.", "argumentaire": "Il consolide les bases et gagne en autonomie : formules conditionnelles (SI, SOMME.SI), références absolues, tris, filtres et graphiques simples. Résultat : des tableaux du quotidien fiables, plus rapides à mettre à jour. Certification Tosa, éligible au CPF dès la première formation, sans nombre de jours minimum.", "reponses": {"Formation": "Formules conditionnelles, tris, filtres et graphiques pour fiabiliser ses tableaux."}}, {"formation": "bur-powerpoint-initiation", "pourquoi": "Pour présenter son activité à ses partenaires, banquiers ou équipes.", "argumentaire": "Il apprend à construire une présentation claire et visuelle : mise en page, thèmes, images, graphiques, animations sobres et diffusion. Résultat : des supports qui valorisent son message en réunion ou devant un client. Certification Tosa, éligible au CPF dès la première formation, sans nombre de jours minimum.", "reponses": {"Formation": "Construire des présentations claires, visuelles et dynamiques."}}]$j$::jsonb || (
    select coalesce(jsonb_agg(case when x->>'pourquoi' like 'Le plus adapté : %' then jsonb_set(x, '{pourquoi}', to_jsonb('Ensuite, pour aller plus loin : ' || substr(x->>'pourquoi', 18))) else x end order by o), '[]'::jsonb)
    from jsonb_array_elements(coalesce(data->'parcours', '[]'::jsonb)) with ordinality t(x, o))), updated_at = now()
where id = 'bur-005' and not exists (select 1 from jsonb_array_elements(coalesce(data->'parcours', '[]'::jsonb)) x where x->>'formation' = 'bur-excel-consolidation');

insert into public.profils (id, data, updated_at) values ('bur-006', $j${"nom": "Débutant(e) en informatique, reprise d'activité ou reconversion", "categorie": "Emploi et transition", "categories": ["Emploi et transition"], "ordre": 6, "besoin": "Prendre confiance avec l'ordinateur et les logiciels de bureau.", "besoinDetail": {"situation": "Utilise peu ou pas l'ordinateur ; reprend une activité, se reconvertit ou vise un poste administratif.", "difficulte": "Peu à l'aise avec les fichiers, la messagerie et les logiciels ; peur de mal faire.", "attente": "Devenir autonome sur les tâches de base et rassurer un futur employeur avec une certification."}, "motsCles": "débutant, grand débutant, reprise d'activité, reconversion, retour à l'emploi, demandeur d'emploi, France Travail, ordinateur, informatique, bases, bureautique, Word, Excel, CPF", "parcours": [{"formation": "bur-initier-informatique", "pourquoi": "Le plus adapté pour un vrai débutant : les bases de l'ordinateur d'abord.", "argumentaire": "Il prend en main l'ordinateur pas à pas : clavier, souris, fichiers et dossiers, messagerie, internet et premiers pas sur les logiciels de bureau. Résultat : il gagne en confiance et devient autonome sur les tâches de base, avant d'aller vers Word et Excel.", "reponses": {"Formation": "Prendre en main l'ordinateur, les fichiers, la messagerie et internet."}}, {"formation": "bur-excel-initiation", "pourquoi": "Ensuite, ou s'il connaît déjà les bases de l'ordinateur : ses premiers tableaux.", "argumentaire": "Il apprend à créer un tableau propre, saisir et mettre en forme ses données, écrire ses premières formules (somme, moyenne, pourcentages) et imprimer correctement. Résultat : des tableaux simples qu'il construit seul, sans peur de « casser » le fichier. Certification Tosa, éligible au CPF dès la première formation, sans nombre de jours minimum.", "reponses": {"Formation": "Créer, mettre en forme et imprimer ses premiers tableaux avec des formules simples."}}, {"formation": "bur-word-initiation", "pourquoi": "Pour rédiger courriers, CV et documents professionnels.", "argumentaire": "Il apprend à rédiger et mettre en forme courriers, notes et comptes rendus : mise en page, tableaux, images, modèles et impression. Résultat : des documents professionnels soignés, produits plus vite. Certification Tosa, éligible au CPF dès la première formation, sans nombre de jours minimum.", "reponses": {"Formation": "Rédiger et mettre en forme courriers, notes et documents professionnels."}}], "complements": [], "domaine": "bur", "reponses": {}}$j$::jsonb, now())
on conflict (id) do nothing;

insert into public.profils (id, data, updated_at) values ('bur-007', $j${"nom": "Secrétaire, assistant(e), agent d'accueil", "categorie": "Accueil et relation client", "categories": ["Accueil et relation client", "Administratif et commercial"], "ordre": 7, "besoin": "Produire plus vite des courriers, documents et tableaux soignés.", "besoinDetail": {"situation": "Rédige courriers, comptes rendus et documents, tient quelques tableaux de suivi, prépare parfois des présentations.", "difficulte": "Mises en forme refaites à la main, courriers en nombre ressaisis, tableaux peu fiables.", "attente": "Des documents homogènes et rapides à produire, et des outils maîtrisés et reconnus par une certification."}, "motsCles": "secrétaire, assistante, assistant, agent d'accueil, standardiste, accueil, courriers, comptes rendus, Word, publipostage, Excel, PowerPoint, mise en forme, documents professionnels", "parcours": [{"formation": "bur-word-initiation", "pourquoi": "Le plus adapté si elle met en forme ses documents « à la main ».", "argumentaire": "Il apprend à rédiger et mettre en forme courriers, notes et comptes rendus : mise en page, tableaux, images, modèles et impression. Résultat : des documents professionnels soignés, produits plus vite. Certification Tosa, éligible au CPF dès la première formation, sans nombre de jours minimum.", "reponses": {"Formation": "Rédiger et mettre en forme courriers, notes et documents professionnels."}}, {"formation": "bur-word-perfectionnement", "pourquoi": "Si elle maîtrise déjà Word : styles, modèles et publipostage.", "argumentaire": "Il gagne du temps sur les documents longs et répétitifs : styles, sommaire automatique, modèles, publipostage pour les courriers en nombre. Résultat : des documents homogènes et des envois groupés sans ressaisie. Certification Tosa, éligible au CPF dès la première formation, sans nombre de jours minimum.", "reponses": {"Formation": "Styles, documents longs, modèles et publipostage."}}, {"formation": "bur-excel-initiation", "pourquoi": "Pour ses tableaux de suivi (plannings, listes, relevés).", "argumentaire": "Il apprend à créer un tableau propre, saisir et mettre en forme ses données, écrire ses premières formules (somme, moyenne, pourcentages) et imprimer correctement. Résultat : des tableaux simples qu'il construit seul, sans peur de « casser » le fichier. Certification Tosa, éligible au CPF dès la première formation, sans nombre de jours minimum.", "reponses": {"Formation": "Créer, mettre en forme et imprimer ses premiers tableaux avec des formules simples."}}, {"formation": "bur-powerpoint-initiation", "pourquoi": "Si elle prépare des supports de réunion ou de présentation.", "argumentaire": "Il apprend à construire une présentation claire et visuelle : mise en page, thèmes, images, graphiques, animations sobres et diffusion. Résultat : des supports qui valorisent son message en réunion ou devant un client. Certification Tosa, éligible au CPF dès la première formation, sans nombre de jours minimum.", "reponses": {"Formation": "Construire des présentations claires, visuelles et dynamiques."}}], "complements": [{"formation": "col-workspace", "pourquoi": "Travailler en équipe avec Gmail, Drive, Meet et Docs."}], "domaine": "bur", "reponses": {}}$j$::jsonb, now())
on conflict (id) do nothing;

insert into public.profils (id, data, updated_at) values ('bur-008', $j${"nom": "Utilisateur(trice) d'Excel autodidacte qui veut progresser", "categorie": "Administratif et commercial", "categories": ["Administratif et commercial", "Gestion et management"], "ordre": 8, "besoin": "Structurer ses connaissances d'Excel et passer au niveau supérieur.", "besoinDetail": {"situation": "Utilise Excel tous les jours, appris « sur le tas », avec des tableaux de plus en plus complexes.", "difficulte": "Lacunes et mauvaises habitudes, formules recopiées sans les comprendre, peur de se tromper.", "attente": "Gagner en méthode et en efficacité, et faire reconnaître son niveau par un score Tosa."}, "motsCles": "Excel, autodidacte, appris sur le tas, progresser, niveau, formules, RECHERCHEV, RECHERCHEX, tableaux croisés dynamiques, TCD, graphiques, Tosa, certification, CPF", "parcours": [{"formation": "bur-excel-consolidation", "pourquoi": "À vérifier : sait écrire des formules simples mais hésite sur SI, filtres et références.", "argumentaire": "Il consolide les bases et gagne en autonomie : formules conditionnelles (SI, SOMME.SI), références absolues, tris, filtres et graphiques simples. Résultat : des tableaux du quotidien fiables, plus rapides à mettre à jour. Certification Tosa, éligible au CPF dès la première formation, sans nombre de jours minimum.", "reponses": {"Formation": "Formules conditionnelles, tris, filtres et graphiques pour fiabiliser ses tableaux."}}, {"formation": "bur-excel-perfectionnement", "pourquoi": "S'il maîtrise les formules courantes : recherches et tableaux croisés.", "argumentaire": "Il passe un cap : fonctions de recherche (RECHERCHEX), mise en forme conditionnelle, tableaux croisés dynamiques et graphiques adaptés. Résultat : des analyses et des synthèses produites en quelques minutes à partir de ses données. Certification Tosa, éligible au CPF dès la première formation, sans nombre de jours minimum.", "reponses": {"Formation": "Fonctions de recherche, tableaux croisés dynamiques et graphiques pour analyser ses données."}}, {"formation": "bur-excel-expert", "pourquoi": "S'il utilise déjà les tableaux croisés : viser le niveau expert.", "argumentaire": "Pour l'utilisateur déjà à l'aise avec les tableaux croisés : fonctions avancées, outils d'analyse et de simulation, tableaux de bord élaborés. Résultat : une maîtrise complète d'Excel, reconnue par un score Tosa de niveau expert. Certification Tosa, éligible au CPF dès la première formation, sans nombre de jours minimum.", "reponses": {"Formation": "Fonctions avancées, outils d'analyse et tableaux de bord élaborés."}}, {"formation": "bur-excel-power", "pourquoi": "Pour aller plus loin : automatiser l'import et l'analyse de données avec Power Query, Pivot et BI.", "reponses": {"Formation": "Importer, nettoyer et croiser ses données avec Power Query, Pivot et BI."}}], "complements": [], "domaine": "bur", "reponses": {}}$j$::jsonb, now())
on conflict (id) do nothing;

update public.domaines set data = data || jsonb_build_object('categories', coalesce(data->'categories', '[]'::jsonb) || $j$["Emploi et transition", "Accueil et relation client"]$j$::jsonb,
  'motsClesCategories', coalesce(data->'motsClesCategories', '{}'::jsonb) || $j${"Emploi et transition": "débutant, reprise d'activité, reconversion, demandeur d'emploi, France Travail, CPF, retour à l'emploi, bases de l'informatique", "Accueil et relation client": "accueil, secrétariat, standard, courriers, documents, agent d'accueil, assistante"}$j$::jsonb), updated_at = now()
where id = 'bur' and not (coalesce(data->'categories', '[]'::jsonb) ? 'Emploi et transition');

update public.formations set data = jsonb_set(data, '{modules,0}', (data->'modules'->0) || $j${"positionnement": "Questionnaire de positionnement Excel (obligatoire avant l'inscription)", "questionnaire": true, "questionnaireType": "Formulaire Excel"}$j$::jsonb), updated_at = now()
where id in ('bur-excel-initiation', 'bur-excel-consolidation', 'bur-excel-perfectionnement', 'bur-excel-expert') and not ((data->'modules'->0) ? 'positionnement');

-- Vérification : sous-profils Bureautique et leurs formations dans l'ordre
select id, data->>'nom' as sous_profil, (select string_agg(x->>'formation', ' → ' order by o) from jsonb_array_elements(data->'parcours') with ordinality t(x, o)) as formations
from public.profils where data->>'domaine' = 'bur' order by id;
